  1265  bool Ip6::ShouldForwardToThread(const MessageInfo &aMessageInfo) const
  1266  {
  1267      bool rval = false;
  1268
  1269      if (aMessageInfo.GetSockAddr().IsMulticast())
  1270      {
  1271          // multicast
  1272          ExitNow(rval = true);
  1273      }
  1274      else if (aMessageInfo.GetSockAddr().IsLinkLocal())
  1275      {
  1276          // on-link link-local address
  1277          ExitNow(rval = true);
  1278      }
  1279      else if (IsOnLink(aMessageInfo.GetSockAddr()))
  1280      {
  1281          // on-link global address
  1282          ExitNow(rval = true);
  1283      }
  1284      else if (Get<ThreadNetif>().RouteLookup(aMessageInfo.GetPeerAddr(), aMessageInfo.GetSockAddr(), NULL) ==
  1285               OT_ERROR_NONE)
  1286      {
  1287          // route
  1288          ExitNow(rval = true);
  1289      }
  1290      else
  1291      {
  1292          ExitNow(rval = false);
  1293      }
  1294
  1295  exit:
  1296      return rval;
  1297  }
